# A web-based application for real-time code collaboration, annotation, and debugging

import os
import json
import uuid
import hashlib
import threading
import time
from datetime import datetime
from typing import Dict, List, Optional, Any, Tuple
from dataclasses import dataclass, field, asdict
from enum import Enum
from functools import wraps
from collections import defaultdict
import secrets


# =====================
# Data Models & Enums
# =====================

class UserRole(Enum):
    VIEWER = "viewer"
    REVIEWER = "reviewer"
    DEVELOPER = "developer"
    ADMIN = "admin"


class TaskStatus(Enum):
    PENDING = "pending"
    IN_REVIEW = "in_review"
    NEEDS_FIX = "needs_fix"
    RESOLVED = "resolved"
    ESCALATED = "escalated"
    CLOSED = "closed"


class AnnotationType(Enum):
    COMMENT = "comment"
    SUGGESTION = "suggestion"
    QUESTION = "question"
    ERROR = "error"


@dataclass
class User:
    id: str
    username: str
    email: str
    role: UserRole = UserRole.DEVELOPER
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())

    def to_dict(self):
        return asdict(self)


@dataclass
class Annotation:
    id: str
    snippet_id: str
    user_id: str
    line_start: int
    line_end: int
    content: str
    type: AnnotationType = AnnotationType.COMMENT
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    resolved: bool = False
    resolved_by: Optional[str] = None
    resolved_at: Optional[str] = None

    def to_dict(self):
        return asdict(self)


@dataclass
class CodeSnippet:
    id: str
    title: str
    content: str
    language: str
    created_by: str
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    updated_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    annotations: List[Annotation] = field(default_factory=list)
    version: int = 1
    git_commit: Optional[str] = None

    def to_dict(self):
        return asdict(self)


@dataclass
class ChatMessage:
    id: str
    session_id: str
    user_id: str
    content: str
    timestamp: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    snippet_ref: Optional[str] = None  # Reference to a code snippet ID
    error_log: Optional[str] = None

    def to_dict(self):
        return asdict(self)


@dataclass
class ReviewTask:
    id: str
    snippet_id: str
    title: str
    description: str
    status: TaskStatus = TaskStatus.PENDING
    assigned_to: Optional[str] = None
    created_by: str = ""
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    updated_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    history: List[Dict[str, Any]] = field(default_factory=list)

    def to_dict(self):
        return asdict(self)


# =====================
# In-Memory Storage (for demo; in production, replace with DB)
# =====================

class Storage:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.snippets: Dict[str, CodeSnippet] = {}
        self.chat_messages: Dict[str, List[ChatMessage]] = defaultdict(list)
        self.tasks: Dict[str, ReviewTask] = {}
        self.sessions: Dict[str, Dict[str, Any]] = {}  # session_id -> {user_ids, snippet_id, ...}
        self.user_sessions: Dict[str, List[str]] = defaultdict(list)  # user_id -> [session_ids]
        self._lock = threading.RLock()

    def add_user(self, user: User):
        with self._lock:
            self.users[user.id] = user

    def get_user(self, user_id: str) -> Optional[User]:
        with self._lock:
            return self.users.get(user_id)

    def add_snippet(self, snippet: CodeSnippet):
        with self._lock:
            self.snippets[snippet.id] = snippet

    def get_snippet(self, snippet_id: str) -> Optional[CodeSnippet]:
        with self._lock:
            return self.snippets.get(snippet_id)

    def update_snippet(self, snippet: CodeSnippet):
        with self._lock:
            self.snippets[snippet.id] = snippet

    def add_annotation(self, annotation: Annotation):
        with self._lock:
            snippet = self.snippets.get(annotation.snippet_id)
            if snippet:
                snippet.annotations.append(annotation)
                snippet.updated_at = datetime.utcnow().isoformat()

    def get_annotations(self, snippet_id: str) -> List[Annotation]:
        with self._lock:
            snippet = self.snippets.get(snippet_id)
            return snippet.annotations if snippet else []

    def add_chat_message(self, message: ChatMessage):
        with self._lock:
            self.chat_messages[message.session_id].append(message)

    def get_chat_messages(self, session_id: str) -> List[ChatMessage]:
        with self._lock:
            return self.chat_messages.get(session_id, [])

    def add_task(self, task: ReviewTask):
        with self._lock:
            self.tasks[task.id] = task

    def get_task(self, task_id: str) -> Optional[ReviewTask]:
        with self._lock:
            return self.tasks.get(task_id)

    def update_task_status(self, task_id: str, new_status: TaskStatus, user_id: str):
        with self._lock:
            task = self.tasks.get(task_id)
            if task:
                old_status = task.status
                task.status = new_status
                task.updated_at = datetime.utcnow().isoformat()
                task.history.append({
                    "timestamp": task.updated_at,
                    "user_id": user_id,
                    "from_status": old_status.value,
                    "to_status": new_status.value
                })

    def get_user_tasks(self, user_id: str) -> List[ReviewTask]:
        with self._lock:
            return [
                task for task in self.tasks.values()
                if task.assigned_to == user_id or task.created_by == user_id
            ]

    def add_session(self, session_id: str, snippet_id: str, user_id: str):
        with self._lock:
            if session_id not in self.sessions:
                self.sessions[session_id] = {
                    "snippet_id": snippet_id,
                    "user_ids": set(),
                    "created_at": datetime.utcnow().isoformat()
                }
            self.sessions[session_id]["user_ids"].add(user_id)
            self.user_sessions[user_id].append(session_id)

    def get_session_users(self, session_id: str) -> List[str]:
        with self._lock:
            session = self.sessions.get(session_id)
            return list(session["user_ids"]) if session else []

    def remove_user_from_session(self, session_id: str, user_id: str):
        with self._lock:
            if session_id in self.sessions:
                self.sessions[session_id]["user_ids"].discard(user_id)
            if user_id in self.user_sessions:
                self.user_sessions[user_id] = [
                    sid for sid in self.user_sessions[user_id] if sid != session_id
                ]


# =====================
# Authentication & Authorization
# =====================

class AuthService:
    def __init__(self, storage: Storage):
        self.storage = storage
        self.sessions: Dict[str, str] = {}  # token -> user_id

    def register_user(self, username: str, email: str, password: str) -> Optional[User]:
        if any(u.email == email for u in self.storage.users.values()):
            return None
        user_id = str(uuid.uuid4())
        hashed = hashlib.sha256(password.encode()).hexdigest()
        user = User(id=user_id, username=username, email=email)
        self.storage.add_user(user)
        return user

    def login(self, email: str, password: str) -> Optional[str]:
        hashed = hashlib.sha256(password.encode()).hexdigest()
        for user in self.storage.users.values():
            if user.email == email:
                token = secrets.token_urlsafe(32)
                self.sessions[token] = user

