    vcs_integration: Optional[Dict[str, Any]] = None  # e.g., {"repo": "org/repo", "branch": "main"}

# ============= Storage Abstraction =============

class InMemoryStorage:
    """In-memory storage for demo purposes. In production, replace with DB layer."""
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.snippets: Dict[str, CodeSnippet] = {}
        self.annotations: Dict[str, Annotation] = {}
        self.chat_messages: Dict[str, ChatMessage] = {}
        self.tasks: Dict[str, Task] = {}
        self.sessions: Dict[str, CodeReviewSession] = {}

    def add_user(self, user: User):
        self.users[user.id] = user

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    def add_snippet(self, snippet: CodeSnippet):
        self.snippets[snippet.id] = snippet

    def get_snippet(self, snippet_id: str) -> Optional[CodeSnippet]:
        return self.snippets.get(snippet_id)

    def add_annotation(self, annotation: Annotation):
        self.annotations[annotation.id] = annotation

    def get_annotation(self, annotation_id: str) -> Optional[Annotation]:
        return self.annotations.get(annotation_id)

    def add_chat_message(self, message: ChatMessage):
