# ============= Real-Time Communication (Mock) =============

class RealTimeBroker:
    """Mock WebSocket-like real-time communication broker."""
    def __init__(self):
        self.subscribers: Dict[str, Set[str]] = {}  # session_id -> set of user_ids
        self.pending_updates: Dict[str, List[Dict]] = {}

    def subscribe(self, session_id: str, user_id: str):
        if session_id not in self.subscribers:
            self.subscribers[session_id] = set()
        self.subscribers[session_id].add(user_id)
        logger.info(f"User {user_id} subscribed to session {session_id}")

    def unsubscribe(self, session_id: str, user_id: str):
        if session_id in self.subscribers:
            self.subscribers[session_id].discard(user_id)

    def broadcast(self, session_id: str, event_type: str, payload: Dict):
        if session_id in self.subscribers:
            for user_id in self.subscribers[session_id]:
                # In real implementation, push to WebSocket
